//! Blurb sourced from https://github.com/arkworks-rs
//! This library implements the scalar field of the prime-order curve Pallas, generated by
//! [Daira Hopwood](https://github.com/zcash/pasta). The main feature of this
//! curve is that it forms a cycle with Vesta, i.e. its scalar field and base
//! field respectively are the base field and scalar field of Vesta.
//!
//!
//! Curve information:
//! * Base field: q =
//!   28948022309329048855892746252171976963363056481941560715954676764349967630337
//! * Scalar field: r =
//!   28948022309329048855892746252171976963363056481941647379679742748393362948097
//! * Curve equation: y^2 = x^3 + 5
//! * Valuation(q - 1, 2) = 32
//! * Valuation(r - 1, 2) = 32
use crate::bignum::BigNum;
use crate::bignum::derive_bignum;
use crate::params::BigNumParams;

pub global Pallas_Fr_PARAMS: BigNumParams<3, 255> = BigNumParams {
    has_multiplicative_inverse: true,
    modulus: [0x4698fc0994a8dd8c46eb2100000001, 0x22, 0x4000],
    double_modulus: [
        0x018d31f8132951bb188dd64200000002,
        0x01000000000000000000000000000043,
        0x7fff,
    ],
    redc_param: [0x6703f66b572273b914deffffffff12, 0xffffffffffffffffffffffffffddb9, 0x3fffff],
};

#[derive_bignum(3, 255, quote { Pallas_Fr_PARAMS })]
pub struct Pallas_Fr {
    limbs: [u128; 3],
}
